<?php
session_start(); require_once __DIR__ . '/config.php'; require_login();
$pdo = db(); $currentUser = user(); $selected = null; $error = '';
if (isset($_GET['toilet'])) { $statement = $pdo->prepare('SELECT * FROM toilets t JOIN user_toilets ut ON ut.toilet_id=t.id WHERE t.id=? AND ut.user_id=?'); $statement->execute([(int) $_GET['toilet'], $currentUser['id']]); $selected = $statement->fetch(); }
$activeStatement = $pdo->prepare("SELECT s.*, t.code, t.name, t.building FROM toilet_sessions s JOIN toilets t ON t.id=s.toilet_id WHERE s.user_id=? AND s.status='active' LIMIT 1"); $activeStatement->execute([$currentUser['id']]); $active = $activeStatement->fetch();
function store_camera_photos(PDO $pdo, int $sessionId, string $phase, string $payload): void {
    if (!$payload) return; $photos = json_decode($payload, true); if (!is_array($photos) || count($photos) > 3) throw new RuntimeException('Please capture up to three photos.');
    if (!is_dir(UPLOAD_DIR)) mkdir(UPLOAD_DIR, 0755, true);
    foreach ($photos as $photo) { if (!preg_match('#^data:image/(jpeg|png|webp);base64,#', $photo, $match)) throw new RuntimeException('Only camera images are accepted.'); $binary = base64_decode(substr($photo, strpos($photo, ',') + 1), true); if ($binary === false || strlen($binary) > 8 * 1024 * 1024) throw new RuntimeException('A camera photo is invalid or too large.'); $extension = $match[1] === 'jpeg' ? 'jpg' : $match[1]; $path = 'uploads/' . bin2hex(random_bytes(12)) . '.' . $extension; file_put_contents(__DIR__ . '/' . $path, $binary); $insert = $pdo->prepare('INSERT INTO session_photos (session_id,phase,file_path) VALUES (?,?,?)'); $insert->execute([$sessionId, $phase, $path]); }
}
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf(); $action = $_POST['action'] ?? '';
    try {
        if ($action === 'check_in') {
            $toiletId = (int) $_POST['toilet_id']; $pdo->beginTransaction();
            $lock = $pdo->prepare("SELECT id FROM toilet_sessions WHERE user_id=? AND toilet_id=? AND status='active' FOR UPDATE"); $lock->execute([$currentUser['id'], $toiletId]); if ($lock->fetch()) throw new RuntimeException('You already have an active check-in for this toilet.');
            $insert = $pdo->prepare("INSERT INTO toilet_sessions (user_id,toilet_id,check_in_at,check_in_comment,status) VALUES (?,?,NOW(),?,'active')"); $insert->execute([$currentUser['id'], $toiletId, trim($_POST['comment'] ?? '')]); $sessionId = (int) $pdo->lastInsertId(); store_camera_photos($pdo, $sessionId, 'before', $_POST['photos'] ?? '');
            if (comment_flags_issue($_POST['comment'] ?? '')) { $flag = $pdo->prepare("UPDATE toilets SET status='attention' WHERE id=? AND status<>'closed'"); $flag->execute([$toiletId]); }
            $pdo->commit(); flash('success', 'Check-in recorded. Keep this visit active until the work is complete.'); redirect('app.php?toilet=' . $toiletId);
        }
        if ($action === 'check_out') {
            if (!$active) throw new RuntimeException('You need an active check-in before checking out.');
            $pdo->beginTransaction(); $update = $pdo->prepare("UPDATE toilet_sessions SET check_out_at=NOW(),check_out_comment=?,status='completed' WHERE id=? AND user_id=? AND status='active'"); $update->execute([trim($_POST['comment'] ?? ''), $active['id'], $currentUser['id']]); if ($update->rowCount() !== 1) throw new RuntimeException('This visit has already been checked out.'); store_camera_photos($pdo, (int) $active['id'], 'after', $_POST['photos'] ?? '');
            $resolvedStatus = comment_flags_issue($_POST['comment'] ?? '') ? 'attention' : 'available';
            $resolve = $pdo->prepare("UPDATE toilets SET status=? WHERE id=? AND status<>'closed'"); $resolve->execute([$resolvedStatus, $active['toilet_id']]);
            $pdo->commit(); flash('success', 'Visit completed and added to shared history.'); redirect('app.php');
        }
    } catch (Throwable $exception) { if ($pdo->inTransaction()) $pdo->rollBack(); $error = $exception->getMessage(); }
}
$toilets = $pdo->prepare("SELECT t.*, EXISTS(SELECT 1 FROM toilet_sessions s WHERE s.toilet_id=t.id AND s.user_id=? AND s.status='active') AS is_active, (SELECT COUNT(*) FROM toilet_sessions s WHERE s.toilet_id=t.id AND s.status='completed') AS visit_count FROM toilets t JOIN user_toilets ut ON ut.toilet_id=t.id WHERE ut.user_id=? ORDER BY t.code"); $toilets->execute([$currentUser['id'], $currentUser['id']]); $toilets = $toilets->fetchAll();
$history = $pdo->prepare('SELECT s.*,t.code,t.name FROM toilet_sessions s JOIN toilets t ON t.id=s.toilet_id WHERE s.user_id=? ORDER BY s.check_in_at DESC LIMIT 6'); $history->execute([$currentUser['id']]); $history = $history->fetchAll(); $flash = $_SESSION['flash'] ?? null; unset($_SESSION['flash']);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My visits · ClearCheck</title><link rel="stylesheet" href="assets/style.css"><script defer src="assets/camera.js"></script></head><body><header class="topbar"><a class="brand" href="app.php"><span class="brand-mark">CC</span><span>ClearCheck</span></a><div class="top-actions"><span class="user-chip"><span class="avatar"> <?= e(strtoupper(substr($currentUser['name'],0,1))) ?></span><?= e($currentUser['name']) ?></span><a class="text-link" href="logout.php">Sign out</a></div></header><main class="page"><div class="page-heading"><div><p class="eyebrow">Student workspace</p><h1>Good morning, <?= e(explode(' ', $currentUser['name'])[0]) ?>.</h1><p class="muted">Choose a toilet to record a cleanliness visit.</p></div><div class="date-stamp"><?= date('l') ?><strong><?= date('d M Y') ?></strong></div></div><?php if ($flash): ?><div class="notice <?= e($flash[0]) ?>"><?= e($flash[1]) ?></div><?php endif; ?><?php if ($error): ?><div class="notice error"><?= e($error) ?></div><?php endif; ?><?php if ($active): ?><section class="active-banner"><div class="pulse-icon">●</div><div><p class="eyebrow">Active check-in</p><h3><?= e($active['code']) ?> · <?= e($active['name']) ?></h3><p class="muted">Started <?= format_time($active['check_in_at']) ?> · <?= e($active['building']) ?></p></div><button class="button dark" onclick="document.getElementById('checkout').scrollIntoView({behavior:'smooth'})">Check out <span>→</span></button></section><?php endif; ?><section><div class="section-title"><div><p class="eyebrow">Your locations</p><h2>Select a toilet</h2></div><span class="count-label"><?= count($toilets) ?> assigned</span></div><div class="toilet-grid"><?php foreach ($toilets as $toilet): ?><a class="toilet-card <?= $selected && $selected['id']===$toilet['id'] ? 'selected' : '' ?>" href="?toilet=<?= $toilet['id'] ?>"><div class="toilet-top"><span class="toilet-code"><?= e($toilet['code']) ?></span><span class="status <?= e($toilet['status']) ?>"><?= $toilet['status']==='attention' ? 'Needs attention' : 'Ready' ?></span></div><h3><?= e($toilet['name']) ?></h3><p><?= e($toilet['building']) ?> · <?= e($toilet['floor_label']) ?></p><footer><?= (int)$toilet['visit_count'] ?> recorded visits <span>↗</span></footer></a><?php endforeach; ?></div></section><?php if ($selected && !$active): ?><section class="work-panel"><div><p class="eyebrow">New visit · <?= e($selected['code']) ?></p><h2>Check in to this toilet</h2><p class="muted">Capture what you find before starting. Camera evidence is required for accountability.</p></div><form method="post" class="visit-form" data-camera-form><input type="hidden" name="csrf" value="<?= csrf() ?>"><input type="hidden" name="action" value="check_in"><input type="hidden" name="toilet_id" value="<?= $selected['id'] ?>"><input type="hidden" name="photos" data-photo-payload><label>Before notes<textarea name="comment" rows="3" placeholder="What needs attention?"></textarea></label><div class="camera-box" data-camera><video autoplay playsinline></video><canvas hidden></canvas><div class="camera-placeholder"><span class="camera-icon">◉</span><strong>Camera evidence</strong><small>Allow camera access, then capture up to 3 photos</small></div><div class="camera-controls"><button class="button outline" type="button" data-start-camera>Open camera</button><button class="button dark" type="button" data-capture disabled>Capture photo</button></div></div><div class="photo-strip" data-photo-strip></div><button class="button primary" type="submit" data-submit disabled>Save check-in <span>→</span></button></form></section><?php elseif ($active): ?><section class="work-panel" id="checkout"><div><p class="eyebrow">Finish visit · <?= e($active['code']) ?></p><h2>Check out when it is clean</h2><p class="muted">Document the finished space. Your original check-in remains part of the permanent history.</p></div><form method="post" class="visit-form" data-camera-form><input type="hidden" name="csrf" value="<?= csrf() ?>"><input type="hidden" name="action" value="check_out"><input type="hidden" name="photos" data-photo-payload><label>After notes<textarea name="comment" rows="3" placeholder="What changed?"></textarea></label><div class="camera-box" data-camera><video autoplay playsinline></video><canvas hidden></canvas><div class="camera-placeholder"><span class="camera-icon">◉</span><strong>Camera evidence</strong><small>Allow camera access, then capture up to 3 photos</small></div><div class="camera-controls"><button class="button outline" type="button" data-start-camera>Open camera</button><button class="button dark" type="button" data-capture disabled>Capture photo</button></div></div><div class="photo-strip" data-photo-strip></div><button class="button primary" type="submit" data-submit disabled>Complete check-out <span>→</span></button></form></section><?php endif; ?><section class="history-section"><div class="section-title"><div><p class="eyebrow">Personal log</p><h2>Recent visits</h2></div><a class="text-link" href="admin.php">View shared history →</a></div><div class="history-list"><?php foreach ($history as $item): ?><div class="history-row"><span class="history-date"><strong><?= format_date($item['check_in_at']) ?></strong><?= format_time($item['check_in_at']) ?></span><span><strong><?= e($item['code']) ?> · <?= e($item['name']) ?></strong><small><?= e($item['check_in_comment']) ?></small></span><span class="history-state <?= $item['status']==='completed' ? 'done' : 'live' ?>"><?= $item['status']==='completed' ? 'Completed' : 'Active' ?></span></div><?php endforeach; if (!$history): ?><p class="muted">No visits recorded yet.</p><?php endif; ?></div></section></main></body></html>
